  "schemaVersion": 1,
  "artifacts": [
    {
      "coordinate": "org.apache.commons:commons-text:1.10.0",
      "filename": "commons-text-1.10.0.jar",
      "sha256": "770cd903fa7b604d1f7ef7ba17f84108667294b2b478be8ed1af3bffb4ae0018"
    },
    {
      "coordinate": "org.apache.commons:commons-lang3:3.12.0",
      "filename": "commons-lang3-3.12.0.jar",
      "sha256": "d919d904486c037f8d193412da0c92e22a9fa24230b9d67a57855c5c31c7e94e"
